package com.shengxu.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.core.metadata.IPage; import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.shengxu.dto.MusicDtos.*; import com.shengxu.entity.*; import com.shengxu.mapper.*; import com.shengxu.utils.BusinessException;
import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.util.StreamUtils; import jakarta.servlet.http.HttpServletResponse; import java.net.*; import java.io.*;
@Service
public class MusicLibraryService {
 private final MusicLibraryMapper library; private final MusicCommentMapper comments; private final MusicShareMapper shares; private final UserMapper users;
 public MusicLibraryService(MusicLibraryMapper l,MusicCommentMapper c,MusicShareMapper s,UserMapper u){library=l;comments=c;shares=s;users=u;}
 public PageView<TrackView> list(Long uid,String q,String filter,long page,long size){var w=new LambdaQueryWrapper<MusicLibrary>().eq(MusicLibrary::getUserId,uid).eq(MusicLibrary::getDeleted,0);if(q!=null&&!q.isBlank()){String term=q.trim();w.and(x->x.like(MusicLibrary::getTitle,term).or().like(MusicLibrary::getStyleTags,term));}String normalized=filter==null?"all":filter.trim().toLowerCase();switch(normalized){case "favorite"->w.eq(MusicLibrary::getFavorite,1);case "generated"->w.eq(MusicLibrary::getSourceType,"GENERATED");case "upload"->w.eq(MusicLibrary::getSourceType,"UPLOAD");case "remix","cover"->w.eq(MusicLibrary::getSourceType,"REMIX");case "all",""->{} default->throw new BusinessException(HttpStatus.BAD_REQUEST,"不支持的音乐库筛选");}w.orderByDesc(MusicLibrary::getCreatedAt);IPage<MusicLibrary> p=library.selectPage(new Page<>(page,Math.min(size,50)),w);return new PageView<>(p.getRecords().stream().map(MusicLibraryService::view).toList(),p.getTotal(),p.getCurrent(),p.getSize());}
 public TrackView get(Long uid,Long id){return view(owned(uid,id));}
 public void delete(Long uid,Long id){MusicLibrary m=owned(uid,id);m.setDeleted(1);library.updateById(m);}
 public TrackView favorite(Long uid,Long id,Boolean value){MusicLibrary m=owned(uid,id);m.setFavorite(Boolean.TRUE.equals(value)?1:0);library.updateById(m);return view(m);}
 public PageView<CommentView> commentList(Long uid,Long id,long page,long size){owned(uid,id);var w=new LambdaQueryWrapper<MusicComment>().eq(MusicComment::getMusicLibraryId,id).orderByDesc(MusicComment::getCreatedAt);IPage<MusicComment> p=comments.selectPage(new Page<>(page,Math.min(size,50)),w);var items=p.getRecords().stream().map(c->{User u=users.selectById(c.getUserId());return new CommentView(c.getId(),id,c.getUserId(),u==null?"用户":u.getUsername(),c.getContent(),c.getCreatedAt(),c.getUserId().equals(uid));}).toList();return new PageView<>(items,p.getTotal(),p.getCurrent(),p.getSize());}
 public CommentView addComment(Long uid,Long id,CommentRequest in){owned(uid,id);String content=in.content().trim();if(content.isBlank())throw new BusinessException(HttpStatus.BAD_REQUEST,"评论不能为空");MusicComment c=new MusicComment();c.setId(com.baomidou.mybatisplus.core.toolkit.IdWorker.getId());c.setMusicLibraryId(id);c.setUserId(uid);c.setContent(content);c.setCreatedAt(java.time.LocalDateTime.now());c.setUpdatedAt(c.getCreatedAt());comments.insert(c);User u=users.selectById(uid);return new CommentView(c.getId(),id,uid,u==null?"用户":u.getUsername(),content,c.getCreatedAt(),true);}
 public void deleteComment(Long uid,Long id,Long commentId){owned(uid,id);MusicComment c=comments.selectById(commentId);if(c==null||!c.getMusicLibraryId().equals(id))throw new BusinessException(HttpStatus.NOT_FOUND,"评论不存在");if(!c.getUserId().equals(uid))throw new BusinessException(HttpStatus.FORBIDDEN,"只能删除自己的评论");comments.deleteById(commentId);}
 public ShareView createShare(Long uid,Long id){MusicLibrary m=owned(uid,id);if(!"SUCCESS".equalsIgnoreCase(m.getStatus())||m.getAudioUrl()==null||m.getAudioUrl().isBlank())throw new BusinessException(HttpStatus.CONFLICT,"作品尚未生成完成");MusicShare s=new MusicShare();s.setId(com.baomidou.mybatisplus.core.toolkit.IdWorker.getId());s.setMusicLibraryId(id);s.setUserId(uid);s.setToken(java.util.UUID.randomUUID().toString().replace("-","")+java.util.UUID.randomUUID().toString().replace("-",""));s.setExpiresAt(java.time.LocalDateTime.now().plusDays(7));s.setAccessCount(0);shares.insert(s);return new ShareView(s.getToken(),s.getExpiresAt());}
 public SharedTrackView shared(String token){MusicShare s=shares.selectOne(new LambdaQueryWrapper<MusicShare>().eq(MusicShare::getToken,token));if(s==null||s.getExpiresAt().isBefore(java.time.LocalDateTime.now()))throw new BusinessException(HttpStatus.NOT_FOUND,"分享链接已失效");MusicLibrary m=library.selectById(s.getMusicLibraryId());if(m==null||Integer.valueOf(1).equals(m.getDeleted())||!"SUCCESS".equalsIgnoreCase(m.getStatus())||m.getAudioUrl()==null)throw new BusinessException(HttpStatus.NOT_FOUND,"作品不存在");s.setAccessCount((s.getAccessCount()==null?0:s.getAccessCount())+1);s.setLastAccessedAt(java.time.LocalDateTime.now());shares.updateById(s);User u=users.selectById(s.getUserId());return new SharedTrackView(m.getId(),m.getTitle(),u==null?"创作者":u.getUsername(),m.getAudioUrl(),m.getCoverUrl(),m.getStyleTags(),m.getDuration(),m.getModelVersion(),m.getCreatedAt());}
 public void download(Long uid,Long id,HttpServletResponse response){MusicLibrary m=owned(uid,id);if(m.getAudioUrl()==null)throw new BusinessException(HttpStatus.CONFLICT,"作品尚未生成完成");try{URI uri=URI.create(m.getAudioUrl());if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||!allowed(uri.getHost()))throw new BusinessException(HttpStatus.BAD_GATEWAY,"音频地址不在允许范围内");URLConnection conn=uri.toURL().openConnection();conn.setConnectTimeout(8000);conn.setReadTimeout(30000);response.setContentType("audio/mpeg");response.setHeader("Content-Disposition","attachment; filename=\"shengxu-"+m.getId()+".mp3\"");try(InputStream in=conn.getInputStream()){StreamUtils.copy(in,response.getOutputStream());}}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(HttpStatus.BAD_GATEWAY,"音频下载失败");}}
 private boolean allowed(String host){String h=host.toLowerCase();return h.equals("suno-api.io")||h.endsWith(".suno-api.io")||h.equals("suno.com")||h.endsWith(".suno.com")||h.equals("suno.ai")||h.endsWith(".suno.ai");}
 private MusicLibrary owned(Long uid,Long id){MusicLibrary m=library.selectById(id);if(m==null||!m.getUserId().equals(uid)||Integer.valueOf(1).equals(m.getDeleted()))throw new BusinessException(HttpStatus.NOT_FOUND,"作品不存在");return m;}
 public static TrackView view(MusicLibrary m){return new TrackView(m.getId(),m.getTaskId(),m.getProviderSongId(),m.getTitle(),m.getStatus(),m.getAudioUrl(),m.getCoverUrl(),m.getLyrics(),m.getStyleTags(),m.getDuration(),m.getModelVersion(),m.getSourceType(),Integer.valueOf(1).equals(m.getFavorite()),m.getCreatedAt());}
}
